const now = new Date();
const until = now.toISOString();
const sinceDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = sinceDate.toISOString();
const owner = $env.GITHUB_OWNER || 'claude-builders-bounty';
const repo = $env.GITHUB_REPO || 'claude-builders-bounty';
const language = ($env.SUMMARY_LANGUAGE || 'EN').toUpperCase();
const destinationWebhookUrl = $env.SUMMARY_WEBHOOK_URL || '';
const githubToken = $env.GITHUB_TOKEN || '';
const anthropicApiKey = $env.ANTHROPIC_API_KEY || '';
const anthropicBaseUrl = $env.ANTHROPIC_BASE_URL || 'https://api.anthropic.com/v1/messages';
if (!destinationWebhookUrl) {
  throw new Error('SUMMARY_WEBHOOK_URL is required. Use a Discord incoming webhook URL.');
}
if (!anthropicApiKey) {
  throw new Error('ANTHROPIC_API_KEY is required to call Claude.');
}
return [{ json: { owner, repo, language, destinationWebhookUrl, githubToken, anthropicApiKey, anthropicBaseUrl, since, until } }];

const config = $json;
const sinceMs = Date.parse(config.since);
const untilMs = Date.parse(config.until);
const withinWindow = (value) => {
  const time = Date.parse(value || '');
  return Number.isFinite(time) && time >= sinceMs && time <= untilMs;
};
const commits = (config.rawActivity.commits || []).slice(0, 100).map((commit) => ({
  sha: String(commit.sha || '').slice(0, 7),
  message: commit.commit?.message?.split('\n')[0] || '(no message)',
  author: commit.commit?.author?.name || commit.author?.login || 'unknown',
  url: commit.html_url
}));
const closedIssues = (config.rawActivity.closedIssues || [])
  .filter((issue) => !issue.pull_request && withinWindow(issue.closed_at))
  .map((issue) => ({ number: issue.number, title: issue.title, user: issue.user?.login || 'unknown', url: issue.html_url }));
const mergedPullRequests = (config.rawActivity.closedPullRequests || [])
  .filter((pr) => pr.merged_at && withinWindow(pr.merged_at))
  .map((pr) => ({ number: pr.number, title: pr.title, author: pr.user?.login || 'unknown', mergedAt: pr.merged_at, url: pr.html_url }));
const languageInstruction = config.language === 'FR'
  ? 'Write the summary in French.'
  : 'Write the summary in English.';
const prompt = `You are preparing a weekly engineering activity narrative for ${config.owner}/${config.repo}. ${languageInstruction}\n\nWindow: ${config.since} to ${config.until}\n\nCommits (${commits.length}):\n${commits.map((c) => `- ${c.sha} ${c.message} by ${c.author}`).join('\n') || '- None'}\n\nClosed issues (${closedIssues.length}):\n${closedIssues.map((issue) => `- #${issue.number} ${issue.title} by ${issue.user}`).join('\n') || '- None'}\n\nMerged PRs (${mergedPullRequests.length}):\n${mergedPullRequests.map((pr) => `- #${pr.number} ${pr.title} by ${pr.author}`).join('\n') || '- None'}\n\nReturn a concise narrative with these sections: Highlights, Shipped Work, Maintenance/Risk, Suggested Follow-ups.`;
return [{ json: {
  ...config,
  activity: { commits, closedIssues, mergedPullRequests },
  claudeRequest: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 1200,
    messages: [{ role: 'user', content: prompt }]
  }
}}];

const config = $items('Build Claude Summary Request')[0].json;
const response = $json;
const summary = Array.isArray(response.content)
  ? response.content.map((part) => part.text || '').filter(Boolean).join('\n\n')
  : JSON.stringify(response, null, 2);
const commits = config.activity.commits.length;
const issues = config.activity.closedIssues.length;
const prs = config.activity.mergedPullRequests.length;
const title = `Weekly dev summary for ${config.owner}/${config.repo}`;
const content = `**${title}**\nWindow: ${config.since} → ${config.until}\nActivity: ${commits} commits, ${issues} closed issues, ${prs} merged PRs\n\n${summary}`;
return [{ json: { destinationWebhookUrl: config.destinationWebhookUrl, content, summary } }];

const config = $json;
const helpers = this.helpers;
const headers = {
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'n8n-weekly-dev-summary'
};
if (config.githubToken) {
  headers.Authorization = `Bearer ${config.githubToken}`;
}
function buildQuery(query = {}) {
  return Object.entries(query)
    .filter(([, value]) => value !== undefined && value !== null && value !== '')
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join('&');
}
async function githubGet(path, query = {}) {
  const baseUrl = `https://api.github.com/repos/${config.owner}/${config.repo}${path}`;
  const queryString = buildQuery(query);
  const url = queryString ? `${baseUrl}?${queryString}` : baseUrl;
  return await helpers.httpRequest({ method: 'GET', url, headers, json: true });
}
const commits = await githubGet('/commits', { since: config.since, until: config.until, per_page: 100 });
const closedIssues = await githubGet('/issues', { state: 'closed', since: config.since, per_page: 100 });
const closedPullRequests = await githubGet('/pulls', { state: 'closed', sort: 'updated', direction: 'desc', per_page: 100 });
return [{ json: { ...config, rawActivity: { commits, closedIssues, closedPullRequests } } }];
